import java.util.*;

class Solution {
    public void reverseString(char[] letters) {
        int i = 0, j = letters.length - 1;
        while (i < j) {
            char t = letters[i];      // swap the outer pair, then move inward
            letters[i++] = letters[j];
            letters[j--] = t;
        }
    }
}

